gwt(){return"\u0645\u0646 \u0623\u0643\u0628\u0631 \u0627\u0644\u0645\u0644\u0627\u0639\u0628 \u0641\u064a \u0627\u0644\u0628\u0644\u0627\u062f"},
gws(){return"\u0644\u0645 \u062a\u0639\u062f \u0647\u0646\u0627\u0643 \u0645\u0631\u062d\u0644\u0629 \u0644\u0644\u062a\u0637\u0648\u064a\u0631. \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0627\u0644\u0622\u0646 \u0636\u0628\u0637 \u0633\u0639\u0631 \u0627\u0644\u062a\u0630\u0627\u0643\u0631 \u062c\u064a\u062f\u064b\u0627 \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0645\u0644\u0639\u0628 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u064a\u062f\u0629."},
